    try {
      for (let i = 0; i < missingIds.length; i += 20) {
        const ids = missingIds.slice(i, i + 20);
        await app.store.find('posts', ids);
        m.redraw();
      }
    } finally {
      this.loading = false;
      m.redraw();
    }
